// TableColumnMeta describes column schema attributes needed for interactive row insertion.
type TableColumnMeta struct {
	Name         string
	DataType     string
	ColumnType   string
	IsNullable   bool
	HasDefault   bool
	DefaultValue string
	Extra        string
	Key          string
}

// IsAutoGenerated returns true when MySQL generates the value automatically (auto_increment or generated columns).
func (c TableColumnMeta) IsAutoGenerated() bool {
	lowerExtra := strings.ToLower(c.Extra)
	return strings.Contains(lowerExtra, "auto_increment") || strings.Contains(lowerExtra, "generated")
}

// IsRequiredOnInsert returns true when the operator must supply a value (NOT NULL, no default, not auto-generated).
func (c TableColumnMeta) IsRequiredOnInsert() bool {
	return !c.IsNullable && !c.HasDefault && !c.IsAutoGenerated()
}

// InsertFieldValue captures the explicit value state of an insertion form input cell.
type InsertFieldValue struct {
	Text          string
	IsNull        bool
	ExplicitEmpty bool
}

// FetchTableColumnsMeta retrieves ordered column schema definitions from INFORMATION_SCHEMA.COLUMNS.
func FetchTableColumnsMeta(ctx context.Context, db *sql.DB, dbName, tableName string) ([]TableColumnMeta, error) {
	if db == nil {
		return nil, fmt.Errorf("database connection is nil")
	}
	if dbName == "" || tableName == "" {
		return nil, fmt.Errorf("database name and table name are required")
	}

	query := `
		SELECT
			COLUMN_NAME,
			DATA_TYPE,
			COLUMN_TYPE,
			IS_NULLABLE,
			COLUMN_DEFAULT,
			EXTRA,
			COLUMN_KEY
		FROM INFORMATION_SCHEMA.COLUMNS
		WHERE TABLE_SCHEMA = ?
		  AND TABLE_NAME = ?
		ORDER BY ORDINAL_POSITION
	`

	rows, err := db.QueryContext(ctx, query, dbName, tableName)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	var cols []TableColumnMeta
	for rows.Next() {
		var name, dataType, colType, nullableStr, extra, key sql.NullString
		var defVal sql.NullString
		if scanErr := rows.Scan(&name, &dataType, &colType, &nullableStr, &defVal, &extra, &key); scanErr != nil {
			continue
		}
		meta := TableColumnMeta{
			Name:         name.String,
			DataType:     dataType.String,
			ColumnType:   colType.String,
			IsNullable:   strings.EqualFold(nullableStr.String, "YES"),
			HasDefault:   defVal.Valid,
			DefaultValue: defVal.String,
			Extra:        extra.String,
			Key:          key.String,
		}
		cols = append(cols, meta)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return cols, nil
}

// ValidateInsertValue checks nullability, required constraints, and numeric types before SQL execution.
func ValidateInsertValue(col TableColumnMeta, val InsertFieldValue) error {
	if val.IsNull {
		if !col.IsNullable {
			return fmt.Errorf("column '%s' is NOT NULL", col.Name)
		}
		return nil
	}

	dt := strings.ToLower(col.DataType)
	isIntType := dt == "tinyint" || dt == "smallint" || dt == "mediumint" || dt == "int" || dt == "integer" || dt == "bigint" || dt == "year"
	isFloatType := dt == "decimal" || dt == "numeric" || dt == "float" || dt == "double" || dt == "real"

	if val.ExplicitEmpty {
		if isIntType || isFloatType {
			return fmt.Errorf("column '%s' (%s) cannot be empty string", col.Name, col.ColumnType)
		}
		return nil
	}

	trimmed := strings.TrimSpace(val.Text)
	if val.Text == "" {
		if col.IsRequiredOnInsert() {
			return fmt.Errorf("column '%s' (%s) is required (NOT NULL without default)", col.Name, col.ColumnType)
		}
		return nil
	}

	if isIntType {
		if _, err := strconv.ParseInt(trimmed, 10, 64); err != nil {
			return fmt.Errorf("column '%s' expects an integer (%s)", col.Name, col.ColumnType)
		}
	} else if isFloatType {
		if _, err := strconv.ParseFloat(trimmed, 64); err != nil {
			return fmt.Errorf("column '%s' expects a numeric value (%s)", col.Name, col.ColumnType)
		}
	}
	return nil
}

// BuildParameterizedInsertQuery builds a parameterized INSERT INTO statement, arguments slice,
// and human-readable preview SQL string from column metadata and form field states.
func BuildParameterizedInsertQuery(dbName, tableName string, cols []TableColumnMeta, values map[string]InsertFieldValue) (string, []interface{}, string, error) {
	if tableName == "" {
		return "", nil, "", fmt.Errorf("table name is required")
	}

	var insertCols []string
	var placeholders []string
	var args []interface{}

	for _, col := range cols {
		val := values[col.Name]
		if err := ValidateInsertValue(col, val); err != nil {
			return "", nil, "", err
		}

		if val.IsNull {
			insertCols = append(insertCols, util.QuoteIdentifier(col.Name))
			placeholders = append(placeholders, "?")
			args = append(args, nil)
			continue
		}

		if val.ExplicitEmpty {
			insertCols = append(insertCols, util.QuoteIdentifier(col.Name))
			placeholders = append(placeholders, "?")
			args = append(args, "")
			continue
		}

		if val.Text != "" {
			insertCols = append(insertCols, util.QuoteIdentifier(col.Name))
			placeholders = append(placeholders, "?")
			args = append(args, val.Text)
			continue
		}

		// Blank input (no explicit empty or null flag):
		// Omit auto_increment/default columns so MySQL applies defaults; otherwise send NULL if nullable.
		if col.IsAutoGenerated() || col.HasDefault {
			continue
		}
		if col.IsNullable {
			insertCols = append(insertCols, util.QuoteIdentifier(col.Name))
			placeholders = append(placeholders, "?")
			args = append(args, nil)
		}
	}

	targetTable := util.QuoteIdentifier(tableName)
	if dbName != "" {
		targetTable = fmt.Sprintf("%s.%s", util.QuoteIdentifier(dbName), util.QuoteIdentifier(tableName))
	}

	var query string
	if len(insertCols) == 0 {
		query = fmt.Sprintf("INSERT INTO %s () VALUES ()", targetTable)
	} else {
		query = fmt.Sprintf("INSERT INTO %s (%s) VALUES (%s)",
			targetTable,
			strings.Join(insertCols, ", "),
			strings.Join(placeholders, ", "))
	}

	previewSQL := phhistory.ReplacePlaceholders(query, args...)
	return query, args, previewSQL, nil
}

// ShowInsertRowModal asynchronously inspects table columns and opens an interactive insertion modal.
func ShowInsertRowModal(app *tview.Application, db *sql.DB, dbName, tableName string, targetTable *tview.Table) {
	if ActiveReadOnly {
		showErrorModal(app, mainFlex, "Action Blocked: Active Connection is in READ-ONLY Mode. Row insertion is disabled.")
		return
	}
	if db == nil || dbName == "" || tableName == "" {
		updateFooterText("Select a base table before inserting a new row.")
		return
	}

	updateFooterText(fmt.Sprintf("Inspecting columns of %s.%s...", dbName, tableName))

	go func() {
		ctx, cancel := context.WithTimeout(context.Background(), 3*time.Second)
		defer cancel()

		cols, err := FetchTableColumnsMeta(ctx, db, dbName, tableName)
		if app == nil {
			return
		}
		app.QueueUpdateDraw(func() {
			if err != nil {
				showErrorModal(app, mainFlex, "Failed to inspect columns for insert: "+err.Error())
				return
			}
			if len(cols) == 0 {
				showErrorModal(app, mainFlex, fmt.Sprintf("No columns found for `%s`.`%s`.", dbName, tableName))
				return
			}
			modal := buildInsertRowModalUI(app, db, dbName, tableName, cols, targetTable)
			app.SetRoot(modal, true)
		})
	}()
}

// formatInsertFieldPlaceholder builds a descriptive placeholder based on column type, default, and nullability.
func formatInsertFieldPlaceholder(col TableColumnMeta, state InsertFieldValue) string {
	if state.IsNull {
		return "[SQL NULL] (Ctrl+N to toggle, or type value)"
	}
	if state.ExplicitEmpty {
		return "[EMPTY STRING \"\"] (Ctrl+E to toggle, or type value)"
	}
	if col.IsAutoGenerated() {
		return "(AUTO_INCREMENT - leave blank)"
	}
	if col.HasDefault {
		return fmt.Sprintf("(default: %s)", col.DefaultValue)
	}
	if col.IsNullable {
		return "(nullable - blank=NULL, Ctrl+E=\"\")"
	}
	return "(required)"
}

// buildInsertRowModalUI constructs the centered dynamic form modal for inserting a row.
func buildInsertRowModalUI(app *tview.Application, db *sql.DB, dbName, tableName string, cols []TableColumnMeta, targetTable *tview.Table) *tview.Flex {
	form := tview.NewForm()
	form.SetBackgroundColor(CurrentTheme.SurfaceBg)
	form.SetFieldBackgroundColor(CurrentTheme.FieldBg)
	form.SetFieldTextColor(CurrentTheme.TextPrimary)
	form.SetLabelColor(CurrentTheme.AccentPrimary)
	form.SetButtonBackgroundColor(CurrentTheme.SelectedBg)
	form.SetButtonTextColor(CurrentTheme.SelectedFg)
	form.SetBorderPadding(1, 1, 2, 2)
	StyleModalBox(form.Box, fmt.Sprintf("Insert New Row: %s.%s", dbName, tableName))

	statusView := tview.NewTextView().
		SetDynamicColors(true).
		SetTextAlign(tview.AlignCenter)
	statusView.SetBackgroundColor(CurrentTheme.HeaderBg)
	statusView.SetText(FormatThemeMarkup(" [aqua]Ctrl+N[-]: Toggle NULL  [gray]│[-]  [aqua]Ctrl+E[-]: Toggle Empty \"\"  [gray]│[-]  [lime]Tab[-]: Next  [gray]│[-]  [yellow]Esc[-]: Cancel"))

	states := make([]InsertFieldValue, len(cols))
	inputs := make([]*tview.InputField, len(cols))

	for i, col := range cols {
		idx := i
		meta := col

		reqMark := ""
		if meta.IsRequiredOnInsert() {
			reqMark = "* "
		}
		keyBadge := ""
		if meta.Key == "PRI" {
			keyBadge = " [PK]"
		} else if meta.Key == "MUL" {
			keyBadge = " [FK]"
		}
		label := fmt.Sprintf("%s%s (%s)%s", reqMark, meta.Name, meta.ColumnType, keyBadge)

		if meta.IsNullable && !meta.HasDefault && !meta.IsAutoGenerated() {
			states[idx].IsNull = true
		}

		input := tview.NewInputField().
			SetLabel(label).
			SetFieldWidth(36).
			SetPlaceholder(formatInsertFieldPlaceholder(meta, states[idx]))
		input.SetFieldBackgroundColor(CurrentTheme.FieldBg)
		input.SetFieldTextColor(CurrentTheme.TextPrimary)

		input.SetChangedFunc(func(text string) {
			if text != "" {
				states[idx].IsNull = false
				states[idx].ExplicitEmpty = false
			}
			states[idx].Text = text
		})

		input.SetInputCapture(func(event *tcell.EventKey) *tcell.EventKey {
			switch event.Key() {
			case tcell.KeyCtrlN:
				if !meta.IsNullable {
					statusView.SetText(FormatThemeMarkup(fmt.Sprintf(" [yellow]Column '%s' is NOT NULL.[-]", meta.Name)))
					return nil
				}
				states[idx].IsNull = !states[idx].IsNull
				states[idx].ExplicitEmpty = false
				if states[idx].IsNull {
					states[idx].Text = ""
					input.SetText("")
				}
				input.SetPlaceholder(formatInsertFieldPlaceholder(meta, states[idx]))
				if states[idx].IsNull {
					statusView.SetText(FormatThemeMarkup(fmt.Sprintf(" [aqua]%s[-]: Set to [yellow::b]SQL NULL[-::-]", meta.Name)))
				} else {
					statusView.SetText(FormatThemeMarkup(fmt.Sprintf(" [aqua]%s[-]: Switched to literal input mode", meta.Name)))
				}
				return nil

			case tcell.KeyCtrlE:
				states[idx].ExplicitEmpty = !states[idx].ExplicitEmpty
				states[idx].IsNull = false
				if states[idx].ExplicitEmpty {
					states[idx].Text = ""
					input.SetText("")
					statusView.SetText(FormatThemeMarkup(fmt.Sprintf(" [aqua]%s[-]: Set to [cyan::b]Empty String \"\"[-::-]", meta.Name)))
				} else {
					statusView.SetText(FormatThemeMarkup(fmt.Sprintf(" [aqua]%s[-]: Cleared empty string override", meta.Name)))
				}
				input.SetPlaceholder(formatInsertFieldPlaceholder(meta, states[idx]))
				return nil
			}
			return event
		})

		inputs[idx] = input
		form.AddFormItem(input)
	}

	closeModal := func() {
		if app == nil {
			return
		}
		if mainFlex != nil {
			layout := CreateLayoutWithFooter(app, mainFlex)
			app.SetRoot(layout, true)
			if targetTable != nil {
				app.SetFocus(targetTable)
			}
		}
	}

	var isSubmitting atomic.Bool

	submitInsert := func() {
		if !isSubmitting.CompareAndSwap(false, true) {
			return
		}

		valMap := make(map[string]InsertFieldValue, len(cols))
		for i, col := range cols {
			val := states[i]
			val.Text = inputs[i].GetText()
			valMap[col.Name] = val
		}

		query, args, previewSQL, buildErr := BuildParameterizedInsertQuery(dbName, tableName, cols, valMap)
		if buildErr != nil {
			isSubmitting.Store(false)
			statusView.SetText(FormatThemeMarkup(" [red::b]Validation Error:[-] " + buildErr.Error()))
			return
		}

		if db == nil {
			isSubmitting.Store(false)
			statusView.SetText(FormatThemeMarkup(" [red::b]Error:[-] Database connection is not active."))
			return
		}

		statusView.SetText(FormatThemeMarkup(" [yellow::b]Inserting row into database...[-::-]"))

		go func() {
			defer isSubmitting.Store(false)
			ctxExec, cancelExec := context.WithTimeout(context.Background(), 5*time.Second)
			defer cancelExec()

			var execRes sql.Result
			var execErr error
			if !IsAutoCommitMode() {
				tx, txErr := EnsureActiveTx(ctxExec, db)
				if txErr != nil {
					execErr = txErr
				} else {
					execRes, execErr = tx.ExecContext(ctxExec, query, args...)
					if execErr == nil {
						RecordMutationInTx(previewSQL, "Row Insert Modal")
					}
				}
			} else {
				execRes, execErr = db.ExecContext(ctxExec, query, args...)
			}

			if app == nil {
				return
			}
			app.QueueUpdateDraw(func() {
				if execErr != nil {
					util.SaveLog("Insert row error: " + execErr.Error())
					statusView.SetText(FormatThemeMarkup(" [red::b]Insert Failed:[-] " + execErr.Error()))
					return
				}

				phhistory.SaveQuery(previewSQL, dbName)
				util.SaveLog(previewSQL)

				var lastID int64
				if execRes != nil {
					lastID, _ = execRes.LastInsertId()
				}

				closeModal()
				msg := fmt.Sprintf("Inserted new row into %s.%s", dbName, tableName)
				if lastID > 0 {
					msg += fmt.Sprintf(" (Last Insert ID: %d)", lastID)
				}
				updateFooterText(msg)

				if activeGridDB != nil && activeGridQuery != "" && targetTable != nil {
					ExecuteQueryAsync(app, activeGridDB, activeGridQuery, targetTable, nil)
				}
			})
		}()
	}

	resetFields := func() {
		for i, col := range cols {
			states[i] = InsertFieldValue{
				IsNull: col.IsNullable && !col.HasDefault && !col.IsAutoGenerated(),
			}
			inputs[i].SetText("")
			inputs[i].SetPlaceholder(formatInsertFieldPlaceholder(col, states[i]))
		}
		statusView.SetText(FormatThemeMarkup(" [gray]Form reset.[-] [aqua]Ctrl+N[-]: Toggle NULL  [gray]│[-]  [aqua]Ctrl+E[-]: Empty \"\""))
	}

	form.
		AddButton(" Insert Row ", submitInsert).
		AddButton(" Reset ", resetFields).
		AddButton(" Cancel ", closeModal)

	form.SetCancelFunc(closeModal)

	contentFlex := tview.NewFlex().SetDirection(tview.FlexRow).
		AddItem(form, 0, 1, true).
		AddItem(statusView, 1, 0, false)

	modalFlex := tview.NewFlex().SetDirection(tview.FlexRow).
		AddItem(nil, 1, 0, false).
		AddItem(tview.NewFlex().SetDirection(tview.FlexColumn).
			AddItem(nil, 4, 0, false).
			AddItem(contentFlex, 0, 1, true).
			AddItem(nil, 4, 0, false),
			0, 1, true).
		AddItem(nil, 1, 0, false)

	modalFlex.SetInputCapture(func(event *tcell.EventKey) *tcell.EventKey {
		if event.Key() == tcell.KeyEscape {
			closeModal()
			return nil
		}
		return event
	})

	return modalFlex
}
